import { useState } from 'react'
import { useForm } from '@tanstack/react-form'
import { zodValidator } from '@tanstack/zod-form-adapter'
import type { ZodTypeAny } from 'zod'
import { z } from 'zod'
import './App.css'

/**
 * A single instance of the Zod validator adapter from `@tanstack/zod-form-adapter`.
 *
 * `zodValidator()` returns the validator factory and calling it once more yields
 * the actual validator object exposing `validate` / `validateAsync`. We reuse this
 * instance for every field so we don't recreate it on each keystroke.
 */
const zodAdapter = zodValidator()()

/**
 * Zod schemas describing the validation rules for each field.
 */
const firstNameSchema = z
  .string()
  .min(2, 'First name must be at least 2 characters')
const lastNameSchema = z
  .string()
  .min(2, 'Last name must be at least 2 characters')
const emailSchema = z
  .string()
  .min(1, 'Email is required')
  .email('Please enter a valid email address')
const passwordSchema = z
  .string()
  .min(6, 'Password must be at least 6 characters')

/**
 * Build an `onChange` field validator that runs a Zod schema through the
 * `@tanstack/zod-form-adapter`. The adapter calls `schema.safeParse(value)`
 * internally and turns any issues into a single error string.
 */
function withZod(schema: ZodTypeAny) {
  return ({ value }: { value: unknown }) =>
    zodAdapter.validate({ value, validationSource: 'field' }, schema)
}

type RegistrationData = {
  firstName: string
  lastName: string
  email: string
  password: string
}

function App() {
  const [step, setStep] = useState<1 | 2>(1)
  const [submittedData, setSubmittedData] = useState<RegistrationData | null>(
    null,
  )

  const form = useForm({
    defaultValues: {
      firstName: '',
      lastName: '',
      email: '',
      password: '',
    } as RegistrationData,
    onSubmit: ({ value }) => {
      setSubmittedData(value)
    },
  })

  // Validate the Step 1 fields before allowing the user to proceed.
  const handleNext = async () => {
    const [firstNameErrors, lastNameErrors] = await Promise.all([
      form.validateField('firstName', 'change'),
      form.validateField('lastName', 'change'),
    ])

    const hasErrors =
      (firstNameErrors as unknown[]).length > 0 ||
      (lastNameErrors as unknown[]).length > 0

    if (!hasErrors) {
      setStep(2)
    }
  }

  const handleBack = () => {
    setStep(1)
  }

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    e.stopPropagation()
    void form.handleSubmit()
  }

  if (submittedData) {
    return (
      <section id="wizard">
        <div id="success-message" className="success-card">
          <h1>Registration successful!</h1>
          <p>Your account has been created with the following details:</p>
          <dl className="submitted-data">
            <div>
              <dt>First name</dt>
              <dd>{submittedData.firstName}</dd>
            </div>
            <div>
              <dt>Last name</dt>
              <dd>{submittedData.lastName}</dd>
            </div>
            <div>
              <dt>Email</dt>
              <dd>{submittedData.email}</dd>
            </div>
            <div>
              <dt>Password</dt>
              <dd>{submittedData.password}</dd>
            </div>
          </dl>
          <button
            type="button"
            className="wizard-btn"
            onClick={() => {
              form.reset()
              setSubmittedData(null)
              setStep(1)
            }}
          >
            Register another account
          </button>
        </div>
      </section>
    )
  }

  return (
    <section id="wizard">
      <h1>Create your account</h1>

      <ol className="stepper">
        <li className={step === 1 ? 'active' : ''}>
          <span className="step-number">1</span>
          <span className="step-label">User info</span>
        </li>
        <li className={step === 2 ? 'active' : ''}>
          <span className="step-number">2</span>
          <span className="step-label">Account info</span>
        </li>
      </ol>

      <form className="registration-form" onSubmit={handleSubmit}>
        {step === 1 && (
          <fieldset className="form-step">
            <legend>Step 1 — User info</legend>

            <form.Field
              name="firstName"
              validators={{ onChange: withZod(firstNameSchema) }}
            >
              {(field) => (
                <div className="field">
                  <label htmlFor={field.name}>First name</label>
                  <input
                    id={field.name}
                    name={field.name}
                    type="text"
                    value={field.state.value}
                    placeholder="Jane"
                    onChange={(e) => field.handleChange(e.target.value)}
                    onBlur={field.handleBlur}
                  />
                  {field.state.meta.errors.length > 0 && (
                    <em className="field-error">
                      {field.state.meta.errors.join(', ')}
                    </em>
                  )}
                </div>
              )}
            </form.Field>

            <form.Field
              name="lastName"
              validators={{ onChange: withZod(lastNameSchema) }}
            >
              {(field) => (
                <div className="field">
                  <label htmlFor={field.name}>Last name</label>
                  <input
                    id={field.name}
                    name={field.name}
                    type="text"
                    value={field.state.value}
                    placeholder="Doe"
                    onChange={(e) => field.handleChange(e.target.value)}
                    onBlur={field.handleBlur}
                  />
                  {field.state.meta.errors.length > 0 && (
                    <em className="field-error">
                      {field.state.meta.errors.join(', ')}
                    </em>
                  )}
                </div>
              )}
            </form.Field>

            <div className="wizard-actions">
              <button
                type="button"
                className="wizard-btn primary"
                onClick={() => void handleNext()}
              >
                Next
              </button>
            </div>
          </fieldset>
        )}

        {step === 2 && (
          <fieldset className="form-step">
            <legend>Step 2 — Account info</legend>

            <form.Field
              name="email"
              validators={{ onChange: withZod(emailSchema) }}
            >
              {(field) => (
                <div className="field">
                  <label htmlFor={field.name}>Email</label>
                  <input
                    id={field.name}
                    name={field.name}
                    type="email"
                    value={field.state.value}
                    placeholder="jane@example.com"
                    onChange={(e) => field.handleChange(e.target.value)}
                    onBlur={field.handleBlur}
                  />
                  {field.state.meta.errors.length > 0 && (
                    <em className="field-error">
                      {field.state.meta.errors.join(', ')}
                    </em>
                  )}
                </div>
              )}
            </form.Field>

            <form.Field
              name="password"
              validators={{ onChange: withZod(passwordSchema) }}
            >
              {(field) => (
                <div className="field">
                  <label htmlFor={field.name}>Password</label>
                  <input
                    id={field.name}
                    name={field.name}
                    type="password"
                    value={field.state.value}
                    placeholder="At least 6 characters"
                    onChange={(e) => field.handleChange(e.target.value)}
                    onBlur={field.handleBlur}
                  />
                  {field.state.meta.errors.length > 0 && (
                    <em className="field-error">
                      {field.state.meta.errors.join(', ')}
                    </em>
                  )}
                </div>
              )}
            </form.Field>

            <div className="wizard-actions">
              <button
                type="button"
                className="wizard-btn"
                onClick={handleBack}
              >
                Back
              </button>
              <form.Subscribe
                selector={(state) => ({
                  canSubmit: state.canSubmit,
                  isSubmitting: state.isSubmitting,
                })}
              >
                {(state) => (
                  <button
                    type="submit"
                    className="wizard-btn primary"
                    disabled={!state.canSubmit || state.isSubmitting}
                  >
                    {state.isSubmitting ? 'Submitting…' : 'Submit'}
                  </button>
                )}
              </form.Subscribe>
            </div>
          </fieldset>
        )}
      </form>
    </section>
  )
}

export default App

#wizard {
  display: flex;
  flex-direction: column;
  gap: 24px;
  place-content: center;
  place-items: center;
  flex-grow: 1;
  padding: 48px 20px;
  text-align: left;
}

#wizard > h1 {
  margin: 0;
}

/* ---------- Stepper ---------- */
.stepper {
  display: flex;
  gap: 8px;
  list-style: none;
  padding: 0;
  margin: 0;
  width: 100%;
  max-width: 420px;
}

.stepper li {
  flex: 1 1 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--social-bg);
  color: var(--text);
  font-size: 15px;
  transition:
    border-color 0.2s,
    color 0.2s,
    background 0.2s;
}

.stepper li.active {
  border-color: var(--accent-border);
  color: var(--text-h);
  background: var(--accent-bg);
}

.step-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1px solid currentColor;
  font-size: 13px;
  font-weight: 600;
}

.step-label {
  font-weight: 500;
}

/* ---------- Form ---------- */
.registration-form {
  width: 100%;
  max-width: 420px;
}

.form-step {
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.form-step legend {
  padding: 0 6px;
  font-size: 15px;
  font-weight: 600;
  color: var(--text-h);
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field label {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-h);
}

.field input {
  font: inherit;
  font-size: 16px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text-h);
  transition:
    border-color 0.2s,
    box-shadow 0.2s;
}

.field input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-bg);
}

.field-error {
  font-style: normal;
  font-size: 13px;
  color: #dc2626;
  min-height: 16px;
}

@media (prefers-color-scheme: dark) {
  .field-error {
    color: #f87171;
  }
}

/* ---------- Actions ---------- */
.wizard-actions {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 4px;
}

.wizard-btn {
  font: inherit;
  font-size: 16px;
  padding: 10px 18px;
  border-radius: 8px;
  cursor: pointer;
  color: var(--text-h);
  background: var(--social-bg);
  border: 1px solid var(--border);
  transition:
    border-color 0.2s,
    background 0.2s,
    box-shadow 0.2s;
}

.wizard-btn:hover:not(:disabled) {
  border-color: var(--accent-border);
}

.wizard-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.wizard-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.wizard-btn.primary {
  color: #fff;
  background: var(--accent);
  border-color: var(--accent);
}

.wizard-btn.primary:hover:not(:disabled) {
  box-shadow: var(--shadow);
}

/* ---------- Success ---------- */
.success-card {
  width: 100%;
  max-width: 480px;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  background: var(--accent-bg);
  border-color: var(--accent-border);
}

.success-card h1 {
  font-size: 32px;
  margin: 0;
}

.success-card p {
  margin: 0;
}

.submitted-data {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 0;
}

.submitted-data div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
}

.submitted-data dt {
  font-weight: 500;
  color: var(--text);
  margin: 0;
}

.submitted-data dd {
  margin: 0;
  color: var(--text-h);
  text-align: right;
  word-break: break-all;
}

@media (max-width: 1024px) {
  #wizard {
    padding: 32px 20px;
  }

  .success-card h1 {
    font-size: 26px;
  }
}
